package com.gameaggregator.webhookservice.application;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.*;import com.gameaggregator.platform.core.common.exception.NotFoundException;import com.gameaggregator.webhookservice.api.WebhookDtos.*;import com.gameaggregator.webhookservice.domain.*;import com.gameaggregator.webhookservice.infrastructure.*;import java.security.SecureRandom;import java.time.Instant;import java.util.*;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service @Transactional public class WebhookService{final WebhookEndpointRepository endpoints;final WebhookDeliveryRepository deliveries;final WebhookSecretCipher cipher;final ObjectMapper json;final SecureRandom random=new SecureRandom();public WebhookService(WebhookEndpointRepository e,WebhookDeliveryRepository d,WebhookSecretCipher c,ObjectMapper j){endpoints=e;deliveries=d;cipher=c;json=j;}public Issued create(Create r){byte[] raw=new byte[32];random.nextBytes(raw);String secret=Base64.getUrlEncoder().withoutPadding().encodeToString(raw);var e=endpoints.save(new WebhookEndpoint(r.tenantId(),r.url(),cipher.encrypt(secret),write(r.eventSubscriptions()),r.environment(),r.timeoutMs(),r.maxRetries()));return new Issued(e.id,secret);}public List<WebhookEndpoint> list(){return endpoints.findAll();}public WebhookEndpoint status(UUID id,Status r){var e=get(id);e.active=r.active();return e;}public WebhookDelivery replay(UUID id){var d=deliveries.findById(id).orElseThrow(()->new NotFoundException("DELIVERY_NOT_FOUND","Delivery was not found"));d.status="PENDING";d.attemptCount=0;d.nextAttemptAt=Instant.now();d.lastError=null;return d;}public List<WebhookDelivery> deliveries(UUID endpointId){return deliveries.findAllByEndpointId(endpointId);}public WebhookEndpoint get(UUID id){return endpoints.findById(id).orElseThrow(()->new NotFoundException("WEBHOOK_NOT_FOUND","Webhook endpoint was not found"));}@KafkaListener(topics="business-events",groupId="webhook-service")public void consume(String message){try{JsonNode n=json.readTree(message);String eventId=n.path("eventId").asText();String type=n.path("type").asText();String environment=n.path("environment").asText();if(eventId.isBlank()||type.isBlank())throw new IllegalArgumentException("Event envelope requires eventId and type");for(var e:endpoints.findAllByActiveTrueAndEnvironment(environment)){Set<String> subscribed=json.readValue(e.eventSubscriptionsJson,new TypeReference<Set<String>>(){});if(subscribed.contains(type)&&!deliveries.existsByEndpointIdAndEventId(e.id,eventId))deliveries.save(new WebhookDelivery(e.id,eventId,type,message));}}catch(Exception e){throw new IllegalArgumentException("Invalid business event",e);}}private String write(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalArgumentException(e);}}}